import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(221,'Inventaire immobilier consolidé à fin 2025 : 254 biens, coût brut 4,266476 Md$, amortissements 257,852 M$, hypothèques/encumbrances 169,909 M$. Industrial, office, retail et terrain ; cet inventaire au coût n’inclut pas toutes les JV non consolidées ni financements immobiliers. L’absence de CTP02/CTP03 dans cette liste ne prouve ni cession ni absence d’exposition.','Schedule III - Real Estate and Accumulated Depreciation as of December 31, 2025','consolidated_property_schedule_excludes_unconsolidated_jv_scope',c='context',measurement_basis='254_properties_historical_cost;not_all_data_center_exposure')
add(222,'Fin 2025 : OP consolidé comme VIE, Quantum/MACOOH001 comme VOE ; autres affiliations sous equity method/FV option, avec promote/puts rendant le retour réel distinct de la valeur pro rata. Revenus JV 549,496 M$ incluent juste valeur, distributions 362,102 M$ distinctes ; cash restreint 48,521 M$. Prêts et financing leases ne sont pas des immeubles détenus au coût. CECL nul sur certains prêts ne signifie pas absence de risque ; aucun segment datacenter autonome.','the actual returns realized may differ from the carrying value of these investments.','jv_fair_value_promote_return_not_received_cash',measurement_basis='FY2025_JV_income549_496m_vs_distributions362_102m;promote_options;restricted_cash')
add(223,'Fin 2025 : dette tierce nominale 2,763978 Md$, maturités 2026 de 274,446 M$. Revolver 2,61 Md$ engagé dont 414 M$ tirés ; accordion jusqu’à 5 Md$ conditionnel. Repo CMBS à 1–3 mois, montant/conditions déterminés par prêteur et appels de collatéral possibles ; moyenne des échéances ne supprime pas ce risque de renouvellement. Financement garanti de prêts/CMBS 757,069 M$ distinct des JV datacenter. Conformité covenants déclarée à date, pas garantie future.','may require the Company to provide additional collateral in the form of cash or securities if the market value of such financed investment declines.','repo_collateral_margin_call_and_short_term_rollover',stage='signed',counterparty_evidence='anonymous',measurement_basis='Dec2025_repo1_3month_tenor;otherborrowings757_069m;not_committed_cash_accordion')
add(224,'Exercice 2025 : un segment consolidé, revenus 275,774 M$ et résultat segment 491,207 M$. La définition inclut revenu/juste valeur des JV et exclut certains coûts non cash ; ce résultat ne représente pas une marge cash IA. Management fees 80,727 M$ et performance allocation 97,76 M$ restent des coûts du fonds, distincts d’apports clients ou de loyers.','one operating segment and one reportable segment','single_segment_no_hpc_profit_disaggregation',c='context',measurement_basis='FY2025_segment491_207m_includes_JV_FV;not_HPC_cashflow')
add(225,'Amazon représente 25,2 % des loyers et 11,6 % de la valeur nette comptable des actifs à fin 2025, avec garanties de la maison mère sur les filiales locataires. Il s’agit du périmètre des propriétés louées directement ; aucune preuve que ces actifs soient tous IA et aucun ratio de concentration des JV CoreWeave déduit. McDermott est sous 10 % mais conservé pour comparaison.','Assets leased to subsidiaries of and guaranteed by Amazon.com, Inc.','direct_tenant_concentration_not_all_jv_ai_exposure',counterparty='Amazon',counterparty_evidence='named',measurement_basis='Dec2025_NBV11_6percent;FYrent25_2percent;not_AI_attribution')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
